proofScript:
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';

const source = '/home/genie/workspace/repos/mikro';
const evidence = '.genie/brainstorms/mikro-engine-split/evidence/';
const before = JSON.parse(readFileSync(`${evidence}PRESERVATION-BEFORE.json`, 'utf8'));
const precommit = JSON.parse(readFileSync(`${evidence}G1-IMPORT-PRECOMMIT.json`, 'utf8'));
const importCommit = process.argv[2] || 'HEAD';
const digest = (path) => createHash('sha256').update(readFileSync(path)).digest('hex');
function git(args, cwd = process.cwd()) {
  const result = spawnSync('git', args, { cwd, encoding: 'utf8' });
  assert.equal(result.status, 0, `git ${args[0]} failed`);
  return result.stdout.trim();
}
assert.equal(git(['rev-parse', `${importCommit}:mikro`]), precommit.sourceTree);
assert.equal(git(['rev-parse', `${before.sourceHead}^{tree}`]), precommit.sourceTree);
git(['merge-base', '--is-ancestor', before.sourceHead, importCommit]);
const parents = git(['show', '-s', '--format=%P', importCommit]).split(' ');
assert.deepEqual(parents, [precommit.executionBase, before.sourceHead]);
assert.equal(git(['rev-parse', 'HEAD'], source), before.sourceHead);
assert.equal(digest(`${source}/.git/index`), before.indexSha256);
for (const [path, expected] of Object.entries(before.trackedUnrelatedWipSha256)) {
  assert.equal(digest(`${source}/${path}`), expected, `Unrelated original WIP changed: ${path}`);
}
assert.equal(digest('/home/genie/.mikro/settings.json'), before.operatorSettingsSha256);
assert.equal(digest('scripts/build-binary.sh'), precommit.rootReleaseBuildSha256);
const paths = git(['diff', '--name-only', '-z', parents[0], importCommit]).split('\0').filter(Boolean);
assert.deepEqual([...paths].sort(), [...precommit.stagedPaths].sort());
const root = JSON.parse(readFileSync('package.json', 'utf8'));
const child = JSON.parse(readFileSync('mikro/package.json', 'utf8'));
assert.equal(root.name, '@automagik/genie');
assert.equal(child.name, 'mikro');
assert.equal(JSON.parse(readFileSync('mikro/package-lock.json', 'utf8')).lockfileVersion, 3);
process.stdout.write(`${JSON.stringify({
  importCommit: git(['rev-parse', importCommit]),
  parents,
  initialMikroTree: precommit.sourceTree,
  exactSourceTree: true,
  preservedOriginalHeadAndIndex: true,
  preservedUnrelatedWipFiles: Object.keys(before.trackedUnrelatedWipSha256).length,
  preservedOperatorSettings: true,
  exactCommittedPathset: true,
  rootReleaseBuildScriptUnchanged: true,
  releaseArtifactSmoke: 'required in Group 9; not claimed by source identity',
  existingRootTestFilenameInventory: precommit.rootBeforeTestFilenameInventory.length,
}, null, 2)}\n`);
